  :root{
    --navy-950:#080d16;
    --navy-900:#0c1b2e;
    --navy-800:#12283f;
    --navy-700:#1b3a5c;
    --navy-600:#2a4d74;
    --blue-400:#6f97bd;
    --gold-300:#f2cfa0;
    --gold-400:#e3b583;
    --gold-500:#c99055;
    --paper:#ffffff;
    --ink:#0b1420;
    --mist:rgba(255,255,255,0.62);

    /* ---- landonorris.com-inspired accent: one loud, flat pop color
       used sparingly as full-bleed blocks + a marquee ticker, playing
       against the quiet navy/gold system used everywhere else. ---- */
    --flare:#ff3d1f;
    --flare-dim:#c72e14;
    --flare-ink:#180500;
  }

  *{box-sizing:border-box;}
  html{
    scroll-behavior:smooth;
    scrollbar-width:thin; /* Firefox */
    scrollbar-color:rgba(227,181,131,0.28) transparent;
  }

  /* thin, low-key scrollbar — present but reads as a hairline, not a UI
     element, so it never competes with the gold progress bar up top */
  ::-webkit-scrollbar{ width:5px; height:5px; }
  ::-webkit-scrollbar-track{ background:transparent; }
  ::-webkit-scrollbar-thumb{
    background:rgba(227,181,131,0.28);
    border-radius:3px;
  }
  ::-webkit-scrollbar-thumb:hover{ background:rgba(227,181,131,0.48); }

  body{
    margin:0;
    background:var(--navy-950);
    color:var(--paper);
    font-family:'Inter',sans-serif;
    -webkit-font-smoothing:antialiased;
    overflow-x:hidden;
  }
  ::selection{background:var(--gold-400);color:var(--navy-950);}

  h1,h2,h3,.display{
    font-family:'Space Grotesk',sans-serif;
    letter-spacing:-0.01em;
    margin:0;
  }
  .mono{
    font-family:'JetBrains Mono',monospace;
    letter-spacing:0.08em;
    text-transform:uppercase;
  }

  a{color:inherit;text-decoration:none;}

  /* ---------- SCROLL PROGRESS ---------- */

  /* ---------- top progressive blur band ----------
     A fixed strip under the nav. Anything scrolling up towards the top line
     passes behind it and defocuses progressively — sharp lower down,
     fully blurred at the line. Layered blurs + masks make the ramp smooth. */
  .top-blur{
    position:fixed;
    top:0; left:0; right:0;
    height:70px;           /* how far down the blur reaches */
    z-index:45;            /* above the page, below the nav (50) */
    pointer-events:none;
  }
  .top-blur .tb{
    position:absolute;
    inset:0;
    display:block;
  }
  .top-blur .l1{
    backdrop-filter:blur(1.5px);
    -webkit-backdrop-filter:blur(1.5px);
    -webkit-mask-image:linear-gradient(to bottom, #000 0%, #000 66%, transparent 100%);
            mask-image:linear-gradient(to bottom, #000 0%, #000 66%, transparent 100%);
  }
  .top-blur .l2{
    backdrop-filter:blur(4px);
    -webkit-backdrop-filter:blur(4px);
    -webkit-mask-image:linear-gradient(to bottom, #000 0%, #000 42%, transparent 78%);
            mask-image:linear-gradient(to bottom, #000 0%, #000 42%, transparent 78%);
  }
  .top-blur .l3{
    backdrop-filter:blur(9px);
    -webkit-backdrop-filter:blur(9px);
    -webkit-mask-image:linear-gradient(to bottom, #000 0%, #000 22%, transparent 55%);
            mask-image:linear-gradient(to bottom, #000 0%, #000 22%, transparent 55%);
  }
  .top-blur .l4{
    backdrop-filter:blur(18px);
    -webkit-backdrop-filter:blur(18px);
    -webkit-mask-image:linear-gradient(to bottom, #000 0%, #000 8%, transparent 34%);
            mask-image:linear-gradient(to bottom, #000 0%, #000 8%, transparent 34%);
    background:linear-gradient(to bottom, rgba(8,13,22,0.5), rgba(8,13,22,0) 80%);
  }
  /* switched off while the white hero panel owns the top of the screen */
  .top-blur{ transition:opacity .3s ease; }
  .top-blur.is-off{ opacity:0; }
  .top-blur.is-off .tb{
    backdrop-filter:none;
    -webkit-backdrop-filter:none;
    background:none;
  }
  @media (max-width:860px){
    .top-blur{ height:54px; }
  }

  .scroll-progress{
    position:fixed;
    top:0;left:0;right:0;
    height:3px;
    z-index:80;
    background:rgba(255,255,255,0.05);
    pointer-events:none;
  }
  .scroll-progress-bar{
    height:100%;
    width:100%;
    transform:scaleX(0);
    transform-origin:left center;
    background:linear-gradient(90deg,var(--gold-500),var(--gold-300) 55%,var(--flare));
    box-shadow:0 0 10px rgba(255,61,31,0.55);
    will-change:transform;
  }

  /* ---------- NAV ---------- */
  .nav{
    position:fixed;
    top:0;left:0;right:0;
    z-index:50;
    display:flex;
    align-items:center;
    justify-content:space-between;
    padding:22px 5vw;
    background:transparent;
    opacity:0;
    pointer-events:none;
    transition:background-color .5s ease, padding .5s ease, border-color .5s ease, opacity .4s ease;
    border-bottom:1px solid transparent;
  }
  .nav.solid{
    /* intentionally no background here — the nav stays a plain floating
       row of text and never sits on a bar/rectangle, at any scroll depth */
  }
  .nav-brand{display:flex;align-items:center;gap:10px;transform-origin:center left;transition:transform .12s ease-out;}
  .nav-brand svg{width:32px;height:auto;display:block;}
  .nav-brand span{font-size:15px;font-weight:600;letter-spacing:0.18em;}
  .nav-right{position:relative; display:flex; align-items:center; gap:14px;}

  .nav-menu-btn{
    position:relative;
    width:38px;
    height:38px;
    display:flex;
    align-items:center;
    justify-content:center;
    background:transparent;
    border:1px solid rgba(255,255,255,0.35);
    border-radius:2px;
    color:var(--paper);
    cursor:pointer;
    padding:0;
    transition:border-color .3s ease, color .3s ease, background-color .3s ease, transform .3s cubic-bezier(.34,1.56,.64,1);
  }
  .nav-menu-btn:hover{
    border-color:var(--gold-400);
    color:var(--gold-400);
    background:rgba(227,181,131,0.08);
    transform:scale(1.06);
  }
  .nav-menu-btn.open{
    border-color:var(--gold-400);
    color:var(--gold-400);
    background:rgba(227,181,131,0.1);
  }
  .nav-menu-btn svg{overflow:visible;}
  .nav-menu-btn .bar{
    transform-box:fill-box;
    transform-origin:50% 50%;
    transition:transform .4s cubic-bezier(.65,0,.35,1), opacity .25s ease;
  }
  .nav-menu-btn.open .bar1{transform:translateY(4.5px) rotate(45deg);}
  .nav-menu-btn.open .bar2{opacity:0; transform:scaleX(0);}
  .nav-menu-btn.open .bar3{transform:translateY(-4.5px) rotate(-45deg);}

  .nav-dropdown{
    position:absolute;
    top:calc(100% + 12px);
    right:0;
    min-width:190px;
    background:rgba(8,13,22,0.97);
    border:1px solid rgba(255,255,255,0.1);
    backdrop-filter:blur(14px);
    box-shadow:0 24px 60px rgba(0,0,0,0.5);
    padding:8px;
    display:flex;
    flex-direction:column;
    gap:2px;
    opacity:0;
    transform-origin:top right;
    transform:translateY(-10px) scale(.94);
    pointer-events:none;
    transition:opacity .3s cubic-bezier(.16,1,.3,1), transform .4s cubic-bezier(.16,1,.3,1);
  }
  .nav-dropdown.open{
    opacity:1;
    transform:translateY(0) scale(1);
    pointer-events:auto;
  }
  .nav-dropdown a{
    display:block;
    padding:11px 14px;
    font-size:13px;
    border-radius:2px;
    color:rgba(255,255,255,0.8);
    opacity:0;
    transform:translateY(-6px);
    border-left:2px solid transparent;
    transition:background-color .2s ease, color .2s ease, opacity .3s ease, transform .3s ease, border-color .2s ease;
  }
  .nav-dropdown.open a{
    opacity:1;
    transform:translateY(0);
  }
  .nav-dropdown.open a:nth-child(1){transition-delay:.06s;}
  .nav-dropdown.open a:nth-child(2){transition-delay:.11s;}
  .nav-dropdown.open a:nth-child(3){transition-delay:.16s;}
  .nav-dropdown.open a:nth-child(4){transition-delay:.21s;}
  .nav-dropdown.open a:nth-child(5){transition-delay:.26s;}
  .nav-dropdown a:hover{
    background:rgba(255,61,31,0.1);
    color:var(--flare);
    border-left-color:var(--flare);
    padding-left:18px;
  }

  /* ---------- HERO ---------- */
  .hero-wrap{
    position:relative;
    height:260vh;
  }
  .hero-stage{
    position:sticky;
    top:0;
    height:100vh;
    width:100%;
    overflow:hidden;
  }
  .stage-bg{
    position:absolute;
    inset:0;
    background:var(--navy-950) url('data:image/png;base64,') center center / cover no-repeat;
  }
  .stage-grid{
    position:absolute;
    inset:0;
    z-index:1;
    width:100%;
    height:100%;
    pointer-events:none;
  }
  .stage-panel{
    position:absolute;
    inset:0;
    z-index:2;
    background:var(--paper);
    box-shadow:0 40px 120px rgba(0,0,0,0.35);
    /* default is a full-bleed, plain white screen — exactly the load state —
       so the page is correct even before any script runs. Scroll position
       is the only thing that ever moves it from there. */
  }
  .stage-panel::after{
    content:"";
    position:absolute;
    inset:0;
    border:1px solid rgba(11,20,32,0.06);
  }

  .stage-logo{
    position:absolute;
    top:50%;
    left:50%;
    width:220px;
    transform:translate(-50%,-50%);
    z-index:5;
    filter:drop-shadow(0 12px 30px rgba(0,0,0,0.25));
  }
  .stage-logo svg{width:100%;display:block;}

  .stage-copy{
    position:absolute;
    left:50%;
    top:50%;
    transform:translate(-50%,-50%);
    text-align:center;
    width:min(680px,84vw);
    opacity:0;
    z-index:4;
  }
  .stage-copy .eyebrow{
    font-size:11px;
    color:var(--gold-300);
    margin-bottom:18px;
    display:block;
    will-change:letter-spacing;
  }
  .stage-copy h1{
    font-size:clamp(32px,5.4vw,60px);
    line-height:1.06;
    font-weight:600;
    color:var(--paper);
  }
  .stage-copy p{
    margin:22px auto 0;
    max-width:460px;
    font-size:16px;
    line-height:1.6;
    color:rgba(243,241,236,0.7);
  }

  /* ----- headline highlight sweep ("win" / "dominate") -----
     A gold marker sweeps left -> right behind the word. A duplicate
     copy of the word (generated from data-word, in black) sits above
     everything, clipped with the exact same keyframes/timing as the
     gold marker — so only the letters the gold has currently reached
     read black; anything the gold hasn't touched yet still shows the
     real white text underneath, and once the gold clears a letter
     (and eventually retracts entirely) that letter goes back to
     white. Nothing flips all at once — it tracks the sweep pixel by
     pixel because both layers share one clip-path animation. */
  .stage-copy h1 .hl{
    position:relative;
    z-index:0;
    display:inline-block;      /* keeps the word intact as one unit... */
    white-space:nowrap;        /* ...so it never breaks mid-word, which was */
    vertical-align:baseline;   /* what made the highlight box balloon across two lines */
    color:var(--paper);        /* real, always-present white text underneath */
  }
  .stage-copy h1 .hl::before{
    content:"";
    position:absolute;
    top:0.03em; bottom:0.03em;      /* snug to the glyphs — no leak above/below */
    left:-0.12em; right:-0.12em;
    z-index:-1;                     /* behind the text */
    border-radius:0;                /* rigid, square corners */
    background:linear-gradient(90deg, var(--gold-500), var(--gold-400) 55%, var(--gold-300));
    box-shadow:0 2px 10px rgba(227,181,131,0.22);
    clip-path:inset(0 100% 0 0);    /* hidden — revealed from the left */
    opacity:0;                      /* belt-and-braces: some browsers don't
                                        clip box-shadow to clip-path, so it
                                        can bleed through as a faint ghost
                                        box even at 0% width — opacity kills
                                        that completely while "hidden" */
  }
  .stage-copy h1 .hl::after{
    content:attr(data-word);
    position:absolute;
    inset:0;                        /* sits exactly over the real text */
    z-index:1;                      /* above the real (white) text */
    color:var(--ink);               /* the "touched" black text */
    white-space:nowrap;
    pointer-events:none;
    clip-path:inset(0 100% 0 0);    /* hidden until the gold reaches it */
    opacity:0;
  }

  /* one-shot "shoowsh": sweep in from the left, cross, exit right — gone.
     Box and black-text overlay share the exact same animation so they
     stay pixel-locked to each other the whole way through. */
  .stage-copy.swept .hl::before,
  .stage-copy.swept .hl::after{
    animation:hlSweep 1.5s cubic-bezier(.22,1,.36,1) forwards;
  }
  .stage-copy.swept .hl:nth-of-type(2)::before,
  .stage-copy.swept .hl:nth-of-type(2)::after{
    animation-delay:.1s;            /* "dominate" follows "win" */
  }

  @keyframes hlSweep{
    0%   { clip-path:inset(0 100% 0 0); opacity:0; }   /* 0ms: fully hidden */
    1%   { opacity:1; }                                 /* appears the instant the sweep starts */
    42%  { clip-path:inset(0 0 0 0); opacity:1; }        /* fully revealed */
    58%  { clip-path:inset(0 0 0 0); opacity:1; }        /* hold */
    99%  { opacity:1; }
    100% { clip-path:inset(0 0 0 100%); opacity:0; }     /* exited right — gone */
  }

  .scroll-cue{
    position:absolute;
    bottom:34px;
    left:50%;
    transform:translateX(-50%);
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:10px;
    font-size:10px;
    color:rgba(11,20,32,0.45);
    z-index:6;
    transition:opacity .4s ease;
  }
  .scroll-cue .line{
    width:1px;
    height:26px;
    background:linear-gradient(rgba(11,20,32,0.5),rgba(11,20,32,0));
    animation:cueMove 1.8s ease-in-out infinite;
  }
  @keyframes cueMove{
    0%{opacity:0.15; transform:scaleY(0.4); transform-origin:top;}
    50%{opacity:1; transform:scaleY(1); transform-origin:top;}
    100%{opacity:0.15; transform:scaleY(0.4); transform-origin:top;}
  }

  /* ---------- SECTIONS ---------- */
  section.block{
    position:relative;
    padding:140px 8vw;
    background:var(--navy-950);
  }
  .kicker{
    font-size:11px;
    color:var(--gold-400);
    margin-bottom:18px;
    display:block;
  }
  .section-head{
    display:flex;
    justify-content:space-between;
    align-items:flex-end;
    gap:40px;
    margin-bottom:64px;
    flex-wrap:wrap;
  }
  .section-head h2{
    font-size:clamp(28px,3.4vw,44px);
    font-weight:600;
    max-width:560px;
    line-height:1.15;
  }
  .section-head p{
    max-width:340px;
    font-size:14px;
    line-height:1.7;
    color:rgba(243,241,236,0.55);
    margin:0;
  }

  /* fleet */
  .fleet-grid{
    display:grid;
    grid-template-columns:repeat(3,1fr);
    gap:1px;
    background:rgba(255,255,255,0.08);
    border:1px solid rgba(255,255,255,0.08);
  }
  .fleet-card{
    background:var(--navy-950);
    padding:36px 30px 30px;
    position:relative;
  }
  .fleet-card .tag{
    font-size:10px;
    color:var(--gold-400);
    margin-bottom:26px;
    display:block;
  }
  .fleet-card h3{
    font-size:22px;
    font-weight:600;
    margin-bottom:8px;
  }
  .fleet-card .desc{
    font-size:13px;
    color:rgba(243,241,236,0.55);
    line-height:1.6;
    margin-bottom:28px;
  }
  .spec-row{
    display:flex;
    justify-content:space-between;
    padding:10px 0;
    border-top:1px solid rgba(255,255,255,0.08);
    font-size:11px;
  }
  .spec-row span:first-child{color:rgba(243,241,236,0.4);}

  @media (max-width:900px){
    .fleet-grid{grid-template-columns:1fr;}
  }

  /* routes */
  .routes-list{
    border-top:1px solid rgba(255,255,255,0.1);
  }
  .route-row{
    display:grid;
    grid-template-columns:120px 1fr 120px 90px;
    align-items:center;
    gap:24px;
    padding:22px 0;
    border-bottom:1px solid rgba(255,255,255,0.1);
    font-size:13px;
  }
  .route-row .code{color:var(--gold-400);font-size:12px;}
  .route-row .path{font-size:17px;font-family:'Space Grotesk',sans-serif;font-weight:500;}
  .route-row .time{color:rgba(243,241,236,0.5);text-align:right;}
  @media (max-width:700px){
    .route-row{grid-template-columns:1fr 1fr;row-gap:6px;}
    .route-row .time{text-align:left;}
  }

  /* membership */
  .tier-grid{
    display:grid;
    grid-template-columns:repeat(3,1fr);
    gap:24px;
  }
  .tier-card{
    border:1px solid rgba(255,255,255,0.1);
    padding:34px 28px;
    display:flex;
    flex-direction:column;
    gap:18px;
    transition:border-color .3s ease, transform .3s ease;
  }
  .tier-card.featured{
    border-color:var(--gold-400);
    background:linear-gradient(180deg, rgba(227,181,131,0.06), transparent 60%);
  }
  .tier-card h3{font-size:18px;font-weight:600;}
  .tier-card .price{font-size:13px;color:rgba(243,241,236,0.5);}
  .tier-card ul{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px;}
  .tier-card li{
    font-size:13px;
    color:rgba(243,241,236,0.72);
    padding-left:16px;
    position:relative;
  }
  .tier-card li::before{
    content:"";
    position:absolute;left:0;top:7px;
    width:5px;height:5px;
    background:var(--gold-400);
  }
  .tier-cta{
    margin-top:auto;
    font-size:11px;
    letter-spacing:0.08em;
    text-transform:uppercase;
    padding-top:16px;
    border-top:1px solid rgba(255,255,255,0.1);
  }
  @media (max-width:900px){ .tier-grid{grid-template-columns:1fr;} }

  /* cta */
  .cta-block{
    text-align:center;
    padding:160px 8vw;
    background:radial-gradient(ellipse at center, var(--navy-800), var(--navy-950) 70%);
  }
  .cta-block h2{
    font-size:clamp(30px,5vw,54px);
    font-weight:600;
    max-width:720px;
    margin:0 auto 30px;
    line-height:1.12;
  }
  .cta-btn{
    display:inline-block;
    margin-top:10px;
    padding:16px 34px;
    background:var(--gold-400);
    color:var(--navy-950);
    font-size:12px;
    font-weight:600;
    letter-spacing:0.08em;
    text-transform:uppercase;
    border-radius:2px;
    transition:background-color .25s ease;
  }
  .cta-btn:hover{background:var(--gold-300);}

  /* footer */
  footer{
    padding:48px 8vw 40px;
    display:flex;
    justify-content:space-between;
    align-items:center;
    border-top:1px solid rgba(255,255,255,0.08);
    font-size:11px;
    color:rgba(243,241,236,0.4);
    flex-wrap:wrap;
    gap:16px;
  }
  footer .foot-brand{display:flex;align-items:center;gap:10px;color:rgba(243,241,236,0.6);}
  footer .foot-brand svg{width:16px;}

  /* about */
  .about-note{
    margin-top:18px;
    font-size:12px;
    line-height:1.7;
    color:rgba(243,241,236,0.45);
  }

  /* live / season */
  .team-line{
    font-size:12px;
    color:rgba(243,241,236,0.6);
    margin-bottom:28px;
  }
  .stat-strip{
    display:grid;
    grid-template-columns:repeat(3,1fr);
    border:1px solid rgba(255,255,255,0.1);
  }
  .stat-cell{
    padding:34px 30px;
    border-right:1px solid rgba(255,255,255,0.1);
  }
  .stat-cell:last-child{border-right:none;}
  .stat-cell .num{
    font-family:'Space Grotesk',sans-serif;
    font-size:clamp(36px,4.2vw,56px);
    font-weight:600;
    color:var(--gold-400);
    line-height:1;
  }
  .stat-cell .lbl{
    margin-top:10px;
    font-size:11px;
    color:rgba(243,241,236,0.5);
  }
  .streak-row{
    display:flex;
    flex-wrap:wrap;
    align-items:baseline;
    gap:16px;
    padding:24px 30px;
    border:1px solid rgba(255,255,255,0.1);
    border-top:none;
    font-size:14px;
    color:rgba(243,241,236,0.75);
    line-height:1.6;
  }
  .live-lower{
    display:grid;
    grid-template-columns:1.3fr 1fr;
    gap:1px;
    background:rgba(255,255,255,0.08);
    border:1px solid rgba(255,255,255,0.08);
    margin-top:40px;
  }
  .next-race, .radio-widget{
    background:var(--navy-950);
    padding:30px;
  }
  .radio-widget{
    display:flex;
    flex-direction:column;
    justify-content:space-between;
  }
  .next-race .lbl, .radio-widget .lbl{
    font-size:11px;
    color:rgba(243,241,236,0.45);
    margin-bottom:14px;
    display:block;
  }
  .next-race .gp{font-size:22px; font-family:'Space Grotesk',sans-serif; font-weight:600;}
  .next-race .track{margin-top:6px; font-size:13px; color:rgba(243,241,236,0.55);}
  .radio-bars{
    display:flex;
    align-items:flex-end;
    gap:3px;
    height:44px;
  }
  .radio-bars span{
    flex:1;
    background:var(--gold-500);
    opacity:0.35;
    transform-origin:bottom;
    transition:opacity .3s ease, background-color .3s ease;
  }
  .radio-widget:hover .radio-bars span{
