    background-image:
      linear-gradient(45deg, var(--navy-950) 25%, transparent 25%, transparent 75%, var(--navy-950) 75%, var(--navy-950)),
      linear-gradient(45deg, var(--navy-950) 25%, transparent 25%, transparent 75%, var(--navy-950) 75%, var(--navy-950));
