  }

  /* bodywork corner-cut, shared by identity / garage / connect / live-lower panels */
  .fleet-card, .car-card, .connect-card, .next-race, .radio-widget{
    clip-path:polygon(0 0, calc(100% - 24px) 0, 100% 24px, 100% 100%, 0 100%);
  }
  .fleet-card, .car-card, .connect-card{ position:relative; overflow:hidden; }

  /* ignition sweep — hairline lights up gold on hover, left to right */
  .fleet-card::after, .car-card::after, .connect-card::after{
    content:"";
    position:absolute;
    left:0; bottom:0;
