  @media (max-width:900px){
    .card-index{ font-size:96px; top:-2px; }
  }

  @media (prefers-reduced-motion: reduce){
    html{scroll-behavior:auto;}
    .stage-panel, .scroll-cue .line{transition:none !important; animation:none !important;}
    .radio-widget:hover .radio-bars span{animation:none !important;}
    .stage-copy h1 .hl, .stage-copy h1 .hl::before, .stage-copy h1 .hl::after{transition:none !important; animation:none !important;}
