/* ============================================================
   DRIVER PORTRAIT — m10 reference.
   Hover the photo: it zooms, ascends above the headline/lines,
   and the thin rules glide smoothly to new x/y values (m11).
   ============================================================ */
.portrait{
  scroll-margin-top:80px;   /* keeps the fixed nav from covering the section on anchor-jump */
  position:relative;
  /* visible (not hidden): the .portrait-stage child clips its own grid,
     rules and photo zoom — but the mv1 pop-in photo must be allowed to
     extend BELOW the stage into the "The Man" section, per the reference
     still. body{overflow-x:hidden} is the horizontal backstop. */
  overflow:visible;
  background:
    radial-gradient(120% 90% at 80% 8%, rgba(42,77,116,0.5), transparent 55%),
    radial-gradient(90% 85% at 10% 90%, rgba(18,40,63,0.9), transparent 62%),
    var(--navy-950);
}
.portrait-stage{
  position:relative;
  min-height:100vh;
  width:100%;
  overflow:hidden;
}
.portrait-grid{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  z-index:0;
  pointer-events:none;
  opacity:1;
}

/* ----- the thin rules (they change x/y on hover) ----- */
.p-rule{
  position:absolute;
  display:block;
  pointer-events:none;
  will-change:transform;
}
.p-rule.v1{
  left:3%; top:0;
  width:1px; height:100%;
  background:var(--flare);
  box-shadow:0 0 10px rgba(255,61,31,0.5);
  transition:transform .8s cubic-bezier(.22,1,.36,1);
}
.p-rule.v2{
  left:6.5%; top:0;
  width:1px; height:100%;
  background:rgba(227,181,131,0.8);
  transition:transform .7s cubic-bezier(.22,1,.36,1) .04s;
}
.p-rule.v3{
  left:20%; top:78%;
  width:1px; height:16%;
  background:rgba(227,181,131,0.75);
  transition:transform .66s cubic-bezier(.22,1,.36,1) .08s;
}
.p-rule.h1{
  left:0; top:5%;
  width:34%; height:1px;
  background:repeating-linear-gradient(90deg, var(--gold-400) 0 6px, transparent 6px 14px);
  transition:transform .72s cubic-bezier(.22,1,.36,1);
}
.p-rule.h2{
  left:0; top:82%;
  width:100%; height:1px;
  background:repeating-linear-gradient(90deg, rgba(227,181,131,0.7) 0 6px, transparent 6px 14px);
  transition:transform .85s cubic-bezier(.22,1,.36,1) .06s;
}
/* hover state (m11): each rule glides to a new position */
.portrait-stage:has(.portrait-photo:hover) .p-rule.v1{ transform:translateX(30vw); }
.portrait-stage:has(.portrait-photo:hover) .p-rule.v2{ transform:translateX(4vw);  }
.portrait-stage:has(.portrait-photo:hover) .p-rule.v3{ transform:translateX(-2vw);}
.portrait-stage:has(.portrait-photo:hover) .p-rule.h1{ transform:translateY(17vh);}
.portrait-stage:has(.portrait-photo:hover) .p-rule.h2{ transform:translateY(-7vh);}

/* ----- top bar ----- */
.portrait-top{
  position:absolute;
  top:4.5%; left:4%; right:4%;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:20px;
  z-index:5;
}
.portrait-brand{ display:flex; align-items:center; gap:12px; }
.portrait-logo{ width:34px; height:34px; display:block; filter:drop-shadow(0 4px 14px rgba(11,47,138,0.5)); }
.portrait-word{ font-size:11px; color:rgba(243,241,236,0.85); letter-spacing:0.14em; }
.portrait-tag{ font-size:11px; color:rgba(243,241,236,0.5); letter-spacing:0.16em; text-align:right; }

/* ----- giant headline (m10) ----- */
.portrait-title{
  position:absolute;
  left:4%; bottom:12%;
  z-index:3;                 /* above the photo by default */
  filter:drop-shadow(0 8px 34px rgba(0,0,0,0.45));
  transition:filter .6s cubic-bezier(.22,1,.36,1), opacity .6s ease;
  scroll-margin-top:72px;    /* anchor target for "The Man" nav link — raised from 120px so the MAX VERSTAPPEN headline rests just under the nav logo (logo bottom ~54px, 18px gap) and just below the 70px top-blur band, crisp and near the top-left logo */
}
.portrait-headline{
  position:static;
  margin:0;
  display:flex;
  align-items:baseline;
  gap:0.13em;
  font-size:clamp(2.6rem, 8.6vw, 9.6rem);
  line-height:1;
  letter-spacing:0;
  text-transform:uppercase;
  white-space:nowrap;
}
/* team line — same face/weight as MAX */
.portrait-sub{
  display:inline-block;  /* shrink-wraps so the tracking can be measured */
  margin:-0.55em 0 0 0;  /* JS indents this to sit under VERSTAPPEN */
  font-family:'Saira Condensed',sans-serif;
  font-weight:100;
  text-transform:uppercase;
  font-size:clamp(11px, 1.15vw, 20px);
  letter-spacing:0.24em;
  white-space:nowrap;
  line-height:1;
  color:rgba(243,241,236,0.78);
}
/* title block defocuses whenever the portrait zooms (hover or auto) */
.portrait-stage:has(.portrait-photo:hover) .portrait-title,
.portrait-stage:has(.portrait-photo.is-auto-zoom) .portrait-title{
  filter:blur(9px) drop-shadow(0 8px 34px rgba(0,0,0,0.45));
  opacity:0.55;
}
.portrait-headline .ph-first{
  font-family:'Saira Condensed',sans-serif;
  font-weight:100;
  font-size:1.115em;   /* fallback — exact ratio applied by JS (cap-height match) */
  color:#ffffff;
  letter-spacing:0.04em;
}
.portrait-headline .ph-last{
  font-family:'Bodoni Moda',serif;
  font-weight:900;
  color:#ffffff;
  letter-spacing:0.01em;
}

/* ----- side quote — fills the open space right of the photo ----- */
.portrait-quote-rail{
  position:absolute;
  top:24%;
  right:8.5%;            /* nudged in from the edge */
  width:auto;            /* hard line breaks decide the width */
  z-index:3;
  pointer-events:none;   /* never blocks the photo hover */
}
.portrait-quote{
  margin:0;
}
.portrait-quote p{
  margin:0;
  font-family:'Bodoni Moda',serif;   /* same face as VERSTAPPEN */
  font-weight:900;
  text-transform:uppercase;
  font-size:clamp(15px, min(2.55vw, 4.2vh), 46px);
  line-height:1.14;
  letter-spacing:0.01em;
  color:rgba(243,241,236,0.92);
  text-align:left;
}
.portrait-quote em{
  font:inherit;              /* one font, one size — colour is the only accent */
  font-style:normal;
  color:var(--gold-400);
}

/* ----- quote lines: whoosh in left -> right, replays every time the
   section comes back into view -----
   Each line sits in an overflow-hidden mask sized to its own text
   (width:fit-content), so the highlight bar tracks the words exactly
   rather than the full column width. The text itself starts off to
   the left (blurred/skewed for speed) and whooshes into place; a
   bright-orange bar sweeps across it in the same pass, and while
   the bar covers a word that word's text is forced black — the
   moment the bar clears it, the word returns to its normal colour
   (white body text, gold em words). Only the animation is black;
   the resting state is untouched. */
.portrait-quote .pq-line{
  position:relative;
  display:block;
  width:fit-content;         /* mask matches the text, not the column */
  overflow:hidden;           /* masks the line while it's off to the left */
}
.portrait-quote .pq-line-in{
  position:relative;
  z-index:1;
  display:inline-block;
  white-space:nowrap;        /* keep the breaks exactly where they are written */
  will-change:transform, opacity, filter;
  opacity:0;
  transform:translateX(-55px) skewX(-9deg);
  filter:blur(7px);
}
.portrait-quote .pq-line-in em{
  will-change:color;
}
/* the sweeping highlight bar itself */
.portrait-quote .pq-line::after{
  content:"";
  position:absolute;
  inset:0;
  z-index:2;
  pointer-events:none;
  background:var(--gold-400);
  box-shadow:0 0 18px rgba(227,181,131,0.45);
  clip-path:inset(0 100% 0 0);   /* hidden off the left until it sweeps */
  opacity:0;
}

.portrait-quote-rail.pq-animate .pq-line-in{
  animation:pqWhoosh .85s cubic-bezier(.19,1,.32,1) both, pqInk .85s linear both;
}
.portrait-quote-rail.pq-animate .pq-line-in em{
  animation:pqInkEm .85s linear both;
}
.portrait-quote-rail.pq-animate .pq-line::after{
  animation:pqHlSweep .85s linear both;
}

.portrait-quote-rail.pq-animate .pq-line:nth-child(1) .pq-line-in,
.portrait-quote-rail.pq-animate .pq-line:nth-child(1) .pq-line-in em,
.portrait-quote-rail.pq-animate .pq-line:nth-child(1)::after{ animation-delay:.05s; }
.portrait-quote-rail.pq-animate .pq-line:nth-child(2) .pq-line-in,
.portrait-quote-rail.pq-animate .pq-line:nth-child(2) .pq-line-in em,
.portrait-quote-rail.pq-animate .pq-line:nth-child(2)::after{ animation-delay:.18s; }
.portrait-quote-rail.pq-animate .pq-line:nth-child(3) .pq-line-in,
.portrait-quote-rail.pq-animate .pq-line:nth-child(3) .pq-line-in em,
.portrait-quote-rail.pq-animate .pq-line:nth-child(3)::after{ animation-delay:.31s; }
.portrait-quote-rail.pq-animate .pq-line:nth-child(4) .pq-line-in,
.portrait-quote-rail.pq-animate .pq-line:nth-child(4) .pq-line-in em,
.portrait-quote-rail.pq-animate .pq-line:nth-child(4)::after{ animation-delay:.44s; }
.portrait-quote-rail.pq-animate .pq-line:nth-child(5) .pq-line-in,
.portrait-quote-rail.pq-animate .pq-line:nth-child(5) .pq-line-in em,
.portrait-quote-rail.pq-animate .pq-line:nth-child(5)::after{ animation-delay:.57s; }
.portrait-quote-rail.pq-animate .pq-line:nth-child(6) .pq-line-in,
.portrait-quote-rail.pq-animate .pq-line:nth-child(6) .pq-line-in em,
.portrait-quote-rail.pq-animate .pq-line:nth-child(6)::after{ animation-delay:.70s; }

@keyframes pqWhoosh{
  0%   { opacity:0; transform:translateX(-55px) skewX(-9deg); filter:blur(7px); }
  60%  { opacity:1; transform:translateX(4px) skewX(1deg); filter:blur(0); }
  100% { opacity:1; transform:translateX(0) skewX(0deg); filter:blur(0); }
}

/* highlight bar: sweeps on, holds a beat, sweeps off to the right */
@keyframes pqHlSweep{
  0%   { clip-path:inset(0 100% 0 0); opacity:0; }
  18%  { opacity:1; }
  38%  { clip-path:inset(0 0 0 0); opacity:1; }   /* fully covering the line */
  62%  { clip-path:inset(0 0 0 0); opacity:1; }   /* brief hold */
  92%  { clip-path:inset(0 0 0 100%); opacity:1; }/* swept clear off the right */
  100% { clip-path:inset(0 0 0 100%); opacity:0; }
}

/* base text: white -> black while the bar is over it -> white again */
@keyframes pqInk{
  0%   { color:rgba(243,241,236,0.92); }
  33%  { color:rgba(243,241,236,0.92); }
  42%  { color:var(--ink); }
  60%  { color:var(--ink); }
  78%  { color:rgba(243,241,236,0.92); }
  100% { color:rgba(243,241,236,0.92); }
}
/* em words: gold -> black while covered -> gold again */
@keyframes pqInkEm{
  0%   { color:var(--gold-400); }
  33%  { color:var(--gold-400); }
  42%  { color:var(--ink); }
  60%  { color:var(--ink); }
  78%  { color:var(--gold-400); }
  100% { color:var(--gold-400); }
}

@media (prefers-reduced-motion: reduce){
  .portrait-quote .pq-line-in,
  .portrait-quote .pq-line-in em{
    opacity:1;
    transform:none;
    filter:none;
    color:inherit;
    animation:none !important;
  }
  .portrait-quote .pq-line::after{
    display:none;
  }
}

/* ----- the photo ----- */
.portrait-photo{
  position:absolute;
  left:11.5%; bottom:26%;
  width:clamp(230px, 22vw, 400px);
  aspect-ratio:4/5;
  margin:0;
  z-index:2;                 /* below the headline... */
  transform-origin:50% 65%;
  will-change:transform;
  transition:transform .75s cubic-bezier(.22,1,.36,1), z-index 0s .55s;
}
.portrait-photo-frame{
  width:100%; height:100%;
  overflow:hidden;
  background:var(--navy-800);
  box-shadow:0 42px 90px rgba(0,0,0,0.55);
  outline:1px solid rgba(255,255,255,0.12);
  outline-offset:-1px;
}
.portrait-photo-frame img{
  width:100%; height:100%;
  object-fit:cover;
  display:block;
  transform:scale(1.01);
  filter:saturate(1.02) contrast(1.02);
  transition:transform .9s cubic-bezier(.22,1,.36,1), filter .6s ease;
}
.portrait-credit{
  position:absolute;
  right:0; top:calc(100% + 10px);
  font-size:10px;
  letter-spacing:0.14em;
  color:rgba(243,241,236,0.85);
  opacity:0;
  transform:translateY(-4px);
  pointer-events:none;
  transition:opacity .45s ease, transform .45s cubic-bezier(.22,1,.36,1), color .4s ease;
}

/* auto-zoom: same look as hover, driven by JS on scroll-into-view */
.portrait-photo.is-auto-zoom{
  z-index:4;
  transform:translateY(6vh) scale(1.13);
  transition:transform .75s cubic-bezier(.22,1,.36,1), z-index 0s 0s;
}
.portrait-photo.is-auto-zoom .portrait-photo-frame img{
  transform:scale(1.12);
  filter:saturate(1.08) contrast(1.05);
}
.portrait-photo.is-auto-zoom .portrait-credit{
  opacity:1;
  transform:translateY(0);
}
.portrait-photo.is-auto-zoom::before{ opacity:1; }
.portrait-stage:has(.portrait-photo.is-auto-zoom) .p-rule.v1{ transform:translateX(30vw); }
.portrait-stage:has(.portrait-photo.is-auto-zoom) .p-rule.v2{ transform:translateX(4vw);  }
.portrait-stage:has(.portrait-photo.is-auto-zoom) .p-rule.v3{ transform:translateX(-2vw); }
.portrait-stage:has(.portrait-photo.is-auto-zoom) .p-rule.h1{ transform:translateY(17vh); }
.portrait-stage:has(.portrait-photo.is-auto-zoom) .p-rule.h2{ transform:translateY(-7vh); }

/* hover: zoom in + ascend above the headline and the rules */
.portrait-photo:hover{
  z-index:4;
  transform:translateY(6vh) scale(1.13);
  transition:transform .75s cubic-bezier(.22,1,.36,1), z-index 0s 0s;
}
.portrait-photo:hover .portrait-photo-frame img{
  transform:scale(1.12);
  filter:saturate(1.08) contrast(1.05);
}
.portrait-photo:hover .portrait-credit{
  opacity:1;
  transform:translateY(0);
}

/* ----- animated signature, drawn on top of the photo ----- */
.portrait-signature{
  position:absolute;
  left:11%; right:1%;
  bottom:38%;
  z-index:3;                 /* above the img, below headline's ascend-state */
  pointer-events:none;
  opacity:0;
  transform:scale(1.85) rotate(-3deg);
  transform-origin:22% 100%;
  filter:drop-shadow(0 6px 16px rgba(0,0,0,0.5));
  transition:opacity 1.1s cubic-bezier(.22,1,.36,1), transform 1.1s cubic-bezier(.22,1,.36,1);
}
.portrait-signature svg{
  width:100%;
  height:auto;
  display:block;
  overflow:visible;
}
.portrait-signature #portraitSigPath{ fill:#f4f1ec; }
.portrait-signature #portraitStrokePath{
  fill:none;
  stroke:#fff;
  stroke-width:46;
  stroke-linecap:round;
  stroke-linejoin:round;
}
.portrait-signature #portraitNib{
  fill:#f4f1ec;
  opacity:0;
  filter:drop-shadow(0 0 4px rgba(244,241,236,0.6));
}
/* zoomed-out start -> zooms in to settle on the photo */
.portrait-signature.is-zoomed-in{
  opacity:1;
  transform:scale(1) rotate(-3deg);
}
/* signs itself, holds a beat, then dissolves off the photo */
.portrait-signature.is-fading{
  opacity:0;
  transform:scale(0.94) rotate(-3deg);
  transition:opacity 1.3s ease .15s, transform 1.5s ease .15s;
}

/* soft aura that blooms behind the photo when it ascends */
.portrait-photo::before{
  content:"";
  position:absolute;
  inset:-14%;
  z-index:-1;
  background:radial-gradient(60% 60% at 50% 55%, rgba(227,181,131,0.28), rgba(42,77,116,0.25) 55%, transparent 75%);
  opacity:0;
  transition:opacity .7s ease;
}
.portrait-photo:hover::before{ opacity:1; }

/* ----- responsive ----- */
@media (max-width:860px){
  .portrait-title{
    left:5%; right:5%; bottom:auto; top:15%;
  }
  .portrait-headline{
    white-space:normal;
    font-size:clamp(2.9rem, 15vw, 5.6rem);
    line-height:0.9;
  }
  .portrait-sub{
    font-size:clamp(10px, 2.6vw, 14px);
    letter-spacing:0.3em;
  }
  .portrait-photo{
    left:50%; bottom:5%; top:auto;
    width:min(66vw, 340px);
    transform:translateX(-50%);
  }
  .portrait-photo:hover,
  .portrait-photo.is-auto-zoom{
    transform:translateX(-50%) scale(1.06);
  }
  .portrait-stage:has(.portrait-photo.is-auto-zoom) .p-rule.v1{ transform:translateX(64vw); }
  .p-rule.v2, .p-rule.v3{ display:none; }
  .p-rule.h1{ width:60%; }
  .portrait-stage:has(.portrait-photo:hover) .p-rule.v1{ transform:translateX(64vw); }

  /* quote drops to a full-width block between headline and photo */
  .portrait-quote-rail{
    top:40%;
    bottom:auto;
    left:6%; right:6%;
    width:auto;
    height:auto;
    transform:translateY(-50%);
  }
  .portrait-quote{
    position:static;
    width:100%;
    transform:none;
  }
  .portrait-quote p{
    font-size:clamp(11px, 3.4vw, 17px);
    line-height:1.25;
    text-align:center;
    white-space:normal;
  }
}

@media (prefers-reduced-motion: reduce){
  .p-rule, .portrait-photo, .portrait-photo-frame img, .portrait-title{ transition:none !important; }
  .portrait-stage:has(.portrait-photo:hover) .p-rule{ transform:none; }
  .portrait-stage:has(.portrait-photo.is-auto-zoom) .p-rule{ transform:none; }
  .portrait-photo:hover, .portrait-photo.is-auto-zoom{ transform:none; }
  .portrait-photo::before{ display:none; }
}
@media (max-width:860px) and (prefers-reduced-motion: reduce){
  .portrait-photo:hover, .portrait-photo.is-auto-zoom{ transform:translateX(-50%); }
}

/* ============================================================
   LANDO-NORRIS-INSPIRED REDESIGN
   Applies from "The Man" section down: flat full-bleed color
   blocks, a scrolling marquee ticker, oversized watermark
   numerals, and heavier, tighter display type — set against the
   quiet navy/gold system used above. Structure/content unchanged.
   ============================================================ */

/* ---------- marquee ticker ---------- */
.ln-ticker{
  position:relative;
  overflow:hidden;
  background:var(--flare);
  color:var(--flare-ink);
  padding:16px 0;
  white-space:nowrap;
  border-top:1px solid rgba(0,0,0,0.15);
  border-bottom:1px solid rgba(0,0,0,0.15);
}
.ln-ticker-track{
  display:inline-flex;
  align-items:center;
  gap:48px;
  animation:lnMarquee 26s linear infinite;
  will-change:transform;
}
.ln-ticker:hover .ln-ticker-track{ animation-play-state:paused; }
.ln-ticker span{
  font-family:'Space Grotesk',sans-serif;
  font-weight:700;
  font-size:clamp(16px,2.4vw,28px);
  letter-spacing:-0.01em;
  text-transform:uppercase;
}
.ln-ticker span.outline{
  -webkit-text-stroke:1px var(--flare-ink);
  color:transparent;
}
.ln-ticker span.dot{ font-size:14px; opacity:0.6; }
@keyframes lnMarquee{
  0%{ transform:translateX(0); }
  100%{ transform:translateX(-50%); }
}
@media (prefers-reduced-motion: reduce){
  .ln-ticker-track{ animation:none; }
}

/* ---------- bolder section head ---------- */
section.block{ overflow:hidden; }

/* #about needs real overflow so .mv-gallery-stage (position:sticky)
   can actually track page scroll — overflow:hidden on the ancestor
   was silently killing the sticky effect, so nothing moved at all.
   Nothing in #about relies on the clipping (the marquee that needs
   it lives in a different section), so this is safe to override. */
#about{ overflow:visible; }

/* Raise #about so it visually overlaps the portrait section above it
   and sits as the topmost layer on the page. transform (not margin/
   padding) is used on purpose: it's a purely visual shift that never
   touches layout — text inside #about keeps the exact same wrapping,
   and nothing after it (#live, #records, etc.) gets pushed or pulled.
   The negative margin-bottom just cancels the empty gap the upward
   shift would otherwise leave in the document flow. */
/* .about-lift wraps just the section-head — the piece that overlaps
   up into the portrait section. It's a class (an effect) on purpose,
   not the #about ID: #about is the whole section (gallery + fleet
   cards included), and that shouldn't move. Only this small wrapper
   gets raised. */
.about-lift{
  position:relative;
  z-index:999;               /* topmost layer — above every other element */
  transform:translateY(0);
  margin-bottom:0;
  transition:transform 0.6s ease, margin-bottom 0.6s ease;
}
.about-lift.is-lifted{
  transform:translateY(-450px) scale(0.96);
  margin-bottom:-450px;
}
.section-head .ln-kicker{
  display:inline-flex;
  align-items:center;
  gap:8px;
  padding:6px 12px 6px 8px;
  margin-bottom:20px;
  border:1px solid var(--flare);
  border-radius:100px;
  font-family:'JetBrains Mono',monospace;
  font-size:10px;
  letter-spacing:0.12em;
  text-transform:uppercase;
  color:var(--flare);
}
.section-head .ln-kicker::before{
  content:'';
  width:6px;height:6px;
  border-radius:50%;
  background:var(--flare);
  box-shadow:0 0 0 3px rgba(255,61,31,0.2);
}
.section-head h2{
  font-size:clamp(32px,5vw,58px);
  font-weight:700;
  letter-spacing:-0.02em;
  line-height:1.04;
}

/* ---------- about / fleet: oversized watermark numerals ---------- */
.fleet-card{
  border-top:3px solid transparent;
  transition:border-color .25s ease, background-color .25s ease;
}
.fleet-card:hover{ border-top-color:var(--flare); }
.fleet-card .card-index{
  position:absolute;
  top:8px; right:16px;
  font-family:'Space Grotesk',sans-serif;
  font-size:clamp(64px,7vw,110px);
  font-weight:700;
  line-height:1;
  color:rgba(255,255,255,0.05);
  z-index:0;
  pointer-events:none;
  transition:color .3s ease;
}
.fleet-card:hover .card-index{ color:rgba(255,61,31,0.12); }
.fleet-card .tag .chip{
  background:var(--flare);
  color:var(--flare-ink);
  border-radius:3px;
  padding:1px 6px;
  margin-right:6px;
  font-style:normal;
}
.fleet-card h3{
  font-size:clamp(22px,2vw,26px);
  font-weight:700;
  letter-spacing:-0.01em;
}

/* ---------- live: bold stat blocks, one lit up ---------- */
.stat-strip{ border:none; gap:1px; background:rgba(255,255,255,0.08); }
.stat-cell{
  border-right:none;
  background:var(--navy-950);
  transition:background-color .25s ease, color .25s ease;
}
.stat-cell:hover{ background:var(--flare); }
.stat-cell:hover .num, .stat-cell:hover .lbl{ color:var(--flare-ink); }
.stat-cell .num{
  font-size:clamp(44px,6vw,84px);
  font-weight:700;
  letter-spacing:-0.02em;
}
.streak-row{ border-top:none; }
.next-race .gp{ font-size:clamp(22px,2.4vw,30px); font-weight:700; letter-spacing:-0.01em; }

/* ---------- records: flare hover rail on each row ---------- */
.records-group h3{
  font-size:12px;
  letter-spacing:0.1em;
}
.record-row{ position:relative; padding-left:16px; transition:padding-left .2s ease, border-color .2s ease; }
.record-row::before{
  content:'';
  position:absolute; left:0; top:0; bottom:0;
  width:2px;
  background:var(--flare);
  transform:scaleY(0);
  transform-origin:bottom;
  transition:transform .25s ease;
}
.record-row:hover{ padding-left:22px; border-color:rgba(255,61,31,0.4); }
.record-row:hover::before{ transform:scaleY(1); }
.record-row:hover .val{ color:var(--flare); }
.record-row .val{ transition:color .2s ease; }

/* ---------- garage: giant year numerals, flare underline ---------- */
.garage-cars{ background:rgba(255,255,255,0.08); }
.car-card{
  position:relative;
  overflow:hidden;
  border-bottom:3px solid transparent;
  transition:border-color .25s ease;
}
.car-card:hover{ border-bottom-color:var(--flare); }
.car-card{ padding-top:30px; }
.car-card .yr{
  color:var(--flare);
  font-size:11px;
}
.car-card .yr::after{
  content:attr(data-big);
  position:absolute;
  right:20px; top:10px;
  font-family:'Space Grotesk',sans-serif;
  font-size:clamp(46px,5vw,76px);
  font-weight:700;
  letter-spacing:-0.02em;
  color:rgba(255,255,255,0.05);
  z-index:0;
}
.car-card h4, .car-card p{ position:relative; z-index:1; }

/* ---------- connect: flare hover fill ---------- */
.connect-grid{ background:rgba(255,255,255,0.08); }
.connect-card{
  border-bottom:3px solid transparent;
  transition:background-color .25s ease, border-color .25s ease, transform .25s ease;
}
.connect-card:hover{
  background:var(--flare);
  border-bottom-color:var(--flare-dim);
  transform:translateY(-3px);
}
.connect-card:hover svg{ color:var(--flare-ink); }
.connect-card:hover .plat, .connect-card:hover .handle{ color:var(--flare-ink); }
.connect-card .plat{ font-size:15px; font-weight:700; }

/* ---------- cta: full-bleed flare block, huge black type ---------- */
.cta-block{
  background:var(--flare);
  padding:180px 8vw;
  position:relative;
  overflow:hidden;
}
.cta-block .kicker{
  color:var(--flare-ink);
  opacity:0.7;
  font-size:12px;
}
.cta-block h2{
  color:var(--flare-ink);
  font-size:clamp(38px,7vw,84px);
  font-weight:700;
  letter-spacing:-0.03em;
  line-height:0.98;
}
.cta-btn{
  background:var(--flare-ink);
  color:var(--flare);
  font-weight:700;
  padding:18px 40px;
  border-radius:2px;
}
.cta-btn:hover{ background:var(--navy-950); color:var(--paper); }

/* ---------- footer ---------- */
footer{ background:var(--navy-950); }

@media (max-width:900px){
  .ln-ticker span{ font-size:18px; }
}

/* ============================================================
   MV1 POP-IN PHOTO — reference: user's screenshot.
   Resting state (measured from the reference still, @1332x627):
     top edge sits ~77px below the MAX VERSTAPPEN caps,
     box ~617px wide on the right, extending past the stage
     bottom into "The Man" section. Per user: flush right edge,
     NO border, NO margin, and the image keeps its native 16:9
     (2048x1152) — object-fit:cover, never stretched.
   Hidden at rest (tucked behind the driver portrait, z-index 1).
   Every time the section is reached it fades in, rises from
   behind the driver portrait, and flies diagonally down-right
   across the MAX VERSTAPPEN headline — flipping to z-index 4
   mid-flight so it crosses IN FRONT of the text — then settles.
   Then it becomes a scroll carousel: mv1 -> mv2 -> ... -> mv10
   across one full pass over the section (reversible), 5px drop +
   settle-scale + crossfade per change. See .mv1-stack/.mv1-img.
   ============================================================ */
.mv1-pop{
  position:absolute;
  right:0;              /* flush to the right edge — no margin */
  top:93%;              /* top edge just under the MAX VERSTAPPEN text */
  width:46%;
  aspect-ratio:2048/1152;   /* native 16:9 — aspect ratio never changes */
  margin:0;
  border:0;             /* no borders */
  z-index:1;            /* BEHIND the driver portrait (z2) while hidden */
  opacity:0;
  pointer-events:none;
  /* resting position is the element's natural spot; the hidden/ready
     state parks it behind the driver portrait (upper-left) at 0.45x */
  transform:translate(-54.5vw, -75.6vh) scale(0.45);
  will-change:transform, opacity;
}
/* the 10-photo stack: the whole stack drops 5px per index change
   (transitioned), and each incoming photo crossfades in while settling
   from a slightly larger uniform scale — aspect ratio never distorted */
.mv1-stack{
  position:absolute;
  inset:0;
  overflow:hidden;      /* the 5px drop + settle scale stay inside the box */
  transition:transform .55s cubic-bezier(.22,1,.36,1);
  will-change:transform;
}
.mv1-img{
  position:absolute;
  inset:0;
  width:100%;
  height:100%;
  object-fit:cover;     /* native aspect ratio kept — cover crop, no stretch */
  display:block;
  opacity:0;
  transform:scale(1.06);
  transition:opacity .55s ease, transform .9s cubic-bezier(.22,1,.36,1);
  will-change:opacity, transform;
}
.mv1-img.is-active{
  opacity:1;
  transform:scale(var(--mv-scale,1));
}

/* the flight: one diagonal pass, decelerating into the rest spot */
.mv1-pop.is-pop{
  animation:mv1Flight 1.5s cubic-bezier(.22,1,.36,1) forwards,
            mv1Z 1.5s linear forwards;
}
@keyframes mv1Flight{
  0%   { opacity:0; transform:translate(-54.5vw, -75.6vh) scale(0.45); }
  20%  { opacity:1; }
  100% { opacity:1; transform:translate(0,0) scale(1); }
}
/* z-index flips discretely mid-flight: while still overlapping the
   driver portrait it stays behind (1); once it clears that photo and
   moves across the headline it's in front of the text (4 > z3). */
@keyframes mv1Z{
  0%, 44%  { z-index:1; }
  45%,100% { z-index:4; }
}

@media (max-width:860px){
  .mv1-pop{
    width:76vw;
    top:60%;
    transform:translate(-20vw, -6vh) scale(0.55);
  }
  @keyframes mv1Flight{
    0%   { opacity:0; transform:translate(-20vw, -6vh) scale(0.55); }
    20%  { opacity:1; }
    100% { opacity:1; transform:translate(0,0) scale(1); }
  }
}

@media (prefers-reduced-motion: reduce){
  .mv1-pop.is-pop{
    animation:none !important;
    transform:none;
    opacity:1;
    z-index:4;
  }
  .mv1-stack, .mv1-img{ transition:none !important; }  /* index swaps instantly, no crossfade/drop */
}

/* ============================================================
   MV GALLERY — sticky-stage / panel-stack effect, ported EXACTLY
   from verstappen.css (Rynn's reference). Only the class names
   are renamed (.sticky-stage -> .mv-gallery-stage, .panel-stack
   -> .mv-gallery-track, .panel -> .mv-gallery-frame, .year-tag
   -> .mv-gallery-year, .steps -> .mv-gallery-steps, .step ->
   .mv-gallery-step) so it doesn't collide with .mv1-pop's own
   classes. Every rule/value below is copied as-is from
   verstappen.css — no animation changes. Dropped straight inside
   #about (The Man section), right after the mv1-pop figure.
   ============================================================ */
/* THE FIX: .gallery-overlay takes zero height in #about's layout —
   overflow:visible lets its child (.mv-gallery-wrap, still its full
   natural height: stage + 220vh of steps) render and scroll exactly
   as before, but because THIS wrapper reports height:0 to #about,
   the checker-bar and fleet-grid right after it are completely
   unaffected — they sit immediately below the header, like the
   target screenshot. The gallery photo simply overlays on top of
   them (z-index) while you scroll through its 220vh, like a
   Photoshop layer sitting over content without pushing it. */
.gallery-overlay{
  height:0;
  overflow:visible;
  position:relative;
  z-index:3;
}
.mv-gallery-wrap {
  position: relative;
  width: 100%;
}

.mv-gallery-stage {
  position: sticky;
  top: 8vh;
  height: auto;
  display: flex;
  align-items: flex-start;
  justify-content: flex-end;
  padding-right: 0;
  pointer-events: none;
  z-index: 2;
}

/* Widescreen 16:9 layout for the photo panels — pulled flush to the
   true right edge of the viewport with a negative margin that
   cancels out #about's own 8vw side padding. */
.mv-gallery-track {
  position: relative;
  width: min(55.8vw, 670px);
  aspect-ratio: 16 / 9;
  margin-left: auto;
  margin-right: -8vw;
  overflow: visible;
}

/* Positioned cleanly outside the photo border, flush to the left edge */
.mv-gallery-year {
  position: absolute;
  top: -35px;
  left: 0;
  z-index: 3;
  font-family: "Helvetica Neue", "Inter", "Segoe UI", system-ui, sans-serif;
  font-size: clamp(1rem, 1.6vw, 1.35rem);
  font-weight: 300;
  font-style: normal;
  color: #ffffff;
  letter-spacing: 0.14em;
  pointer-events: none;
  user-select: none;
  text-shadow: 0 4px 18px rgba(0, 0, 0, 0.45);
}

.mv-gallery-frame {
  position: absolute;
  inset: 0;
  border-radius: 0;
  border: 0;
  outline: 0;
  box-shadow: none;
  transition: opacity 0.25s ease-in-out, transform 0.18s ease-out;
  transform-origin: right top;
  opacity: 0;
  overflow: visible;
  will-change: opacity, transform;
}

/* Fills the 16:9 container completely to eliminate any colored bar gaps */
.mv-gallery-frame img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
  border-radius: 0;
  outline: 0;
  border: 0;
}

.mv-gallery-frame.active {
  opacity: 1;
}

.mv-gallery-steps {
  position: relative;
  z-index: 1;
}

.mv-gallery-step {
  /* back to 22vh per your call — 10 steps = 220vh, so the gallery
     runs a full two pages of scroll and flows into #live after it. */
  height: 22vh;
  display: flex;
  align-items: center;
  padding-left: 6vw;
  max-width: 420px;
  color: rgba(255, 255, 255, 0.75);
  font-size: 1.1rem;
  pointer-events: none;
}

.mv-gallery-step > * {
  display: none;
}

@media (max-width: 900px) {
  .mv-gallery-stage {
    justify-content: flex-end;
    padding-right: 0;
  }

  .mv-gallery-track {
    width: 92vw;
    margin-right: 0;
  }

  .mv-gallery-step {
    padding: 0 24px;
    max-width: 100%;
  }
}
